      <path d={GLOVE_PAD} fill="none" stroke="currentColor" strokeWidth="7" strokeLinejoin="round" />
      {GLOVE_GROOVES.map((d, i) => (
        <path key={i} d={d} stroke="currentColor" strokeWidth="6" strokeLinecap="round" />
